{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Octreotide, a cyclic octapeptide, had absolute oral bioavailability of only 0.6 ± 0.4% in healthy volunteers, directly demonstrating that peptide-sized molecules with multiple amide bonds and polar groups have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Plecanatide, a peptide, showed negligible systemic availability after oral administration, with plasma levels below the limit of quantitation, supporting very low oral bioavailability for peptide-like drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "GHRP-6, a peptide GH secretagogue, had oral systemic availability of about 0.3% in humans, requiring extremely high oral doses to match intravenous effects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, had 0.5% oral bioavailability in humans, illustrating that even smaller peptide-like molecules fail to reach 20% oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CGP 38 560, a peptidomimetic renin inhibitor, had <1% oral bioavailability in humans at a 200 mg oral dose, further supporting low oral F for peptide-like structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a ~4.1 kDa, highly polar peptide conjugate with 57 HBDs, 149 rotatable bonds, and very low predicted permeability. All transferable experimental oral bioavailability measurements for peptide and peptidomimetic analogues are below 2%, mostly around 0.3–0.6%, making F ≥ 20% highly unlikely.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the exact query molecule.",
    "Record C12 is internally inconsistent (peptide SMILES vs paliperidone ER label) and was not weighted.",
    "The specific effects of the PEG and fatty-acid conjugate moieties on permeability or transporter-mediated absorption are not directly covered by the peptide analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

